Follow this complete example.
```swift
class Entry {}
class BookEntry: Entry {
    let pages: Int
    init(pages: Int) {
        self.pages = pages
    }
}
func describe(_ entry: Entry) -> String {
    if let book = entry as? BookEntry {
        return "pages=" + String(book.pages)
    }
    return "other"
}
let entry: Entry = BookEntry(pages: 80)
print(entry is BookEntry)
print(describe(entry))
print(describe(Entry()))
```
Output:
```text
true
pages=80
other
```

